package com.example.campsitelottery

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.Calendar
import java.util.Date
import java.util.TimeZone

/**
 * Documentation generated by Claude
 * Tests the rules in [ReviewPolicy].
 */
class ReviewPolicyTest {

    @Test
    fun blankReviewsAreRejected() {
        assertNotNull(ReviewPolicy.validate(""))
        assertNotNull(ReviewPolicy.validate("   \n\t "))
    }

    @Test
    fun lengthLimitAppliesAfterTrimming() {
        val atLimit = "a".repeat(ReviewPolicy.MAX_LENGTH)
        assertNull(ReviewPolicy.validate(atLimit))
        assertNull(ReviewPolicy.validate("  $atLimit  "))
        assertNotNull(ReviewPolicy.validate(atLimit + "a"))
    }

    @Test
    fun normalTextIsAcceptedAndTrimmed() {
        assertNull(ReviewPolicy.validate("Great spot"))
        assertEquals("Great spot", ReviewPolicy.normalize("  Great spot \n"))
    }

    @Test(expected = IllegalArgumentException::class)
    fun requireValidThrowsForBlankText() {
        ReviewPolicy.requireValid(" ")
    }

    @Test
    fun ownersCannotReviewTheirOwnCampsite() {
        assertFalse(ReviewPolicy.canReview(ownerId = "owner", userId = "owner"))
        assertFalse(ReviewPolicy.canReview(ownerId = "owner", userId = ""))
        assertTrue(ReviewPolicy.canReview(ownerId = "owner", userId = "guest"))
    }

    @Test
    fun blankAuthorShowsAsAnonymous() {
        assertEquals(ReviewPolicy.ANONYMOUS_NAME, ReviewPolicy.displayName(Review(authorName = "  ")))
        assertEquals("Sam", ReviewPolicy.displayName(Review(authorName = "Sam")))
    }

    @Test
    fun displayDateFormatsOrSaysJustNow() {
        val cal = Calendar.getInstance(TimeZone.getDefault()).apply { clear(); set(2026, Calendar.NOVEMBER, 22, 12, 0) }
        assertEquals("Nov 22, 2026", ReviewPolicy.displayDate(cal.time))
        assertEquals("Just now", ReviewPolicy.displayDate(null))
    }

    @Test
    fun newestReviewsComeFirstAndUndatedOnTop() {
        val old = Review(userId = "old", updatedAt = Date(1_000))
        val new = Review(userId = "new", updatedAt = Date(2_000))
        val pending = Review(userId = "pending", updatedAt = null)
        assertEquals(
            listOf("pending", "new", "old"),
            ReviewPolicy.sortNewestFirst(listOf(old, pending, new)).map { it.userId },
        )
    }
}
